import torch


def run(inp, weights, minlength):
    return torch.bincount(inp, weights=weights, minlength=minlength)


def gen_inputs(ctx, device):
    shape = ctx["inp__shape"]
    n = int(shape[0]) if len(shape) > 0 else 0
    high = 100
    inp = torch.randint(0, high, (n,), dtype=torch.int64, device=device)
    return {"inp": inp}
